contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "G > 2 and N >= G - 2 and M >= 0",
      "description": "The number of genes G is greater than 2, the number of mutation rules N is at least G-2, and the number of antibodies M is non-negative."
    },
    {
      "id": "P2",
      "expression": "all(2 <= a < G and k >= 1 for a, k in mutation_rules)",
      "description": "Each mutation rule starts with a gene 'a' in the range [2, G-1] and has at least one gene in the replacement sequence."
    },
    {
      "id": "P3",
      "expression": "all(0 <= b < G for rule in mutation_rules for b in rule['sequence'])",
      "description": "All genes in the replacement sequences are valid integers between 0 and G-1."
    },
    {
      "id": "P4",
      "expression": "sum(len(rule['sequence']) for rule in mutation_rules) <= 100",
      "description": "The sum of the lengths of all replacement sequences in the mutation table does not exceed 100."
    },
    {
      "id": "P5",
      "expression": "all(a in [rule['gene'] for rule in mutation_rules] for a in range(2, G))",
      "description": "Every integer from 2 to G-1 appears as a source gene in the mutation table at least once."
    },
    {
      "id": "P6",
      "expression": "all(l >= 1 and all(c in (0, 1) for c in seq) for l, seq in antibodies)",
      "description": "Each antibody has a length l >= 1 and consists only of integers 0 and 1."
    },
    {
      "id": "P7",
      "expression": "sum(l for l, seq in antibodies) <= 50",
      "description": "The sum of the lengths of all antibodies does not exceed 50."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(stdout_lines) == G - 2",
      "description": "The output contains exactly G-2 lines, one for each gene from 2 to G-1."
    },
    {
      "id": "Q2",
      "expression": "all(line.startswith('YES') or (line.startswith('NO ') and line[3:].isdigit()) for line in stdout_lines)",
      "description": "Each output line is either 'YES' or 'NO' followed by a space and a non-negative integer."
    },
    {
      "id": "Q3",
      "expression": "all((line == 'YES') == (not any(virus_is_undetectable(gene, antibodies) for virus in all_terminating_viruses(gene))) for gene, line in zip(range(2, G), stdout_lines))",
      "description": "For each gene, 'YES' is printed if and only if all terminating viruses derivable from that gene contain at least one antibody as a substring; otherwise 'NO' is printed."
    },
    {
      "id": "Q4",
      "expression": "all((int(line.split()[1]) == min_length_undetectable(gene, antibodies)) if line.startswith('NO') else True for gene, line in zip(range(2, G), stdout_lines))",
      "description": "If 'NO' is printed for a gene, the integer following it is the minimum length of a terminating virus derivable from that gene that does not contain any antibody as a substring."
    },
    {
      "id": "Q5",
      "expression": "all((line == 'YES') == (len([v for v in all_terminating_viruses(gene) if virus_is_undetectable(v, antibodies)]) == 0) for gene, line in zip(range(2, G), stdout_lines))",
